{
  "decline_reason": "",
  "claims": [
    {
      "text": "The Act requires the Registrar to give an applicant an opportunity to be heard before rejecting an application.",
      "quotes": [
        {
          "ref": "TMA1995/s33",
          "quote": "(4) The Registrar may not reject an application without giving the applicant an opportunity of being heard."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "Under the Manual’s practice, requesting an ex parte hearing on an examination matter defers acceptance automatically: you do not need to apply separately for an extension of time or deferment.",
      "quotes": [
        {
          "ref": "TMM/Part16/1/1/1",
          "quote": "If an applicant requests an ex parte hearing on an exam matter, the Registrar will defer acceptance of that application. The applicant need not separately apply for an extension of time or deferment."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The hearing-related deferment ends when you withdraw the hearing request or when the Registrar decides to accept or reject the application, whichever happens first.",
      "quotes": [
        {
          "ref": "TMM/Part17/5/5/2",
          "quote": "5.3.1 Where the applicant has made a request to the Registrar to be heard in relation to the application, the Registrar will defer acceptance of the application until the earlier of: (i) the day the applicant withdraws the request to be heard; and (ii) the day the Registrar decides to accept or reject the application."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Deferment preserves the balance of your acceptance period remaining before deferment; it does not give you a fresh full acceptance period.",
      "quotes": [
        {
          "ref": "TMM/Part17/x-annex-a1---deferment-of-acceptance-date---grounds-and-time-limits#1",
          "quote": "Applicant has requested ex parte hearing When the applicant withdraws the request, or the Registrar decides to accept or reject the application Balance of time remaining prior to deferment"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "If a court appeal has begun or an ART review application has been made, the Manual says acceptance is deferred until three months after determination or other disposal, or until expiry of any further time allowed by the relevant court or ART.",
      "quotes": [
        {
          "ref": "TMM/Part17/5/5/2",
          "quote": "5.2.1 Where an appeal to a court has begun or an application to the ART for review has been made, the Registrar will defer acceptance of the application up until 3 months after the determination or other disposal of the appeal or review or until the expiration of such further time as the court to which the appeal, or any further appeal is brought, or the ART, or the court to which any appeal, arising out of the decision of the ART, is brought, allows."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual says the appeal or review deferment is entered when the Registrar is notified, provided the application is still pending.",
      "quotes": [
        {
          "ref": "TMM/Part17/5/5/2",
          "quote": "On such notification, as long as the application is still pending, the deferment will be entered on the system."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual’s annex also records that the balance of time remaining before deferment is preserved for an application under appeal or review.",
      "quotes": [
        {
          "ref": "TMM/Part17/x-annex-a1---deferment-of-acceptance-date---grounds-and-time-limits#1",
          "quote": "TM application under appeal or pending review of Registrar's decision in a court or in the ART, or where a rectification action or appeal or appeal period in relation to such an action is pending 3 months after decision or such time as the prescribed court or ART may allow or, where decision is appealable, 2 months after the issue of that decision Balance of time remaining prior to deferment"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The supplied passages do not establish whether an examiner’s report itself is appealable; the appeal guidance concerns decisions of the Registrar, and these passages may not cover every applicable procedural requirement.",
      "quotes": [],
      "authority": "none"
    }
  ],
